"""Settings: models chosen per agent reach the agent files, roster edits are validated, office options merge."""
import json
import os
import sys
import tempfile
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "src"))

from aiset import settings, sync_names  # noqa: E402

AGENT = """---
name: backend
description: "Emre · Backend Engineer on the Shop team. Owns api (Python)."
tools: Read, Grep, Glob, Bash, Edit, Write
---

You are **Emre, the Backend Engineer** of the Shop team.

<!-- generated by aiset/init_team.py; delete this line to keep your edits -->
"""
PM = """---
name: pm
description: "Deniz · Project Manager of the Shop team."
tools: Agent, Read
---

You are **Deniz, the Project Manager** of the Shop team.

| `backend` | Emre · Backend Engineer | api |

<!-- generated by aiset/init_team.py; delete this line to keep your edits -->
"""
ROSTER = {"team": "Shop", "members": [
    {"id": "pm", "name": "Deniz", "role": "Project Manager", "zone": "pm", "color": "#ec4899", "duty": "Plans."},
    {"id": "backend", "name": "Emre", "role": "Backend Engineer", "zone": "eng", "color": "#22c55e", "duty": "APIs.", "repos": ["api"]},
]}


class ModelLineTest(unittest.TestCase):
    def test_set_replace_remove(self):
        text = sync_names.set_model(AGENT, "sonnet")
        self.assertIn("tools: Read, Grep, Glob, Bash, Edit, Write\nmodel: sonnet\n---\n", text)
        self.assertEqual(sync_names.set_model(text, "sonnet"), text)
        self.assertEqual(text.count("model:"), 1)
        self.assertIn("model: claude-opus-5-5\n", sync_names.set_model(text, "claude-opus-5-5"))
        self.assertEqual(sync_names.set_model(text, ""), AGENT)

    def test_no_frontmatter_is_left_alone(self):
        self.assertEqual(sync_names.set_model("# notes\n", "opus"), "# notes\n")

    def test_pinned_section_before_marker(self):
        roster = json.loads(json.dumps(ROSTER))
        roster["members"][1]["model"] = "haiku"
        text = sync_names.set_pinned(PM, roster)
        self.assertIn("- `backend` (Emre): `haiku`", text)
        self.assertTrue(text.rstrip().endswith("delete this line to keep your edits -->"))
        self.assertEqual(sync_names.set_pinned(text, roster), text)
        del roster["members"][1]["model"]
        self.assertEqual(sync_names.set_pinned(text, roster), PM)


class SyncTest(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.addCleanup(setattr, sync_names, "AGENTS", sync_names.AGENTS)
        sync_names.AGENTS = self.tmp.name
        for name, text in (("backend.md", AGENT), ("pm.md", PM)):
            with open(os.path.join(self.tmp.name, name), "w", encoding="utf-8") as f:
                f.write(text)

    def read(self, name):
        with open(os.path.join(self.tmp.name, name), encoding="utf-8") as f:
            return f.read()

    def test_models_and_names_reach_the_files(self):
        roster = settings.apply_roster(ROSTER, {"members": [{"id": "backend", "name": "Ali", "model": "Opus"}]})
        self.assertEqual(sorted(sync_names.sync(roster)), ["backend", "pm table"])
        backend = self.read("backend.md")
        self.assertIn("model: opus\n", backend)
        self.assertIn("You are **Ali, the Backend", backend)
        self.assertIn("`backend` (Ali): `opus`", self.read("pm.md"))
        self.assertEqual(sync_names.sync(roster), [])
        sync_names.sync(settings.apply_roster(roster, {"members": [{"id": "backend", "model": ""}]}))
        self.assertNotIn("model:", self.read("backend.md"))
        self.assertNotIn("Pinned models", self.read("pm.md"))


class RosterEditTest(unittest.TestCase):
    def test_only_known_fields_change(self):
        out = settings.apply_roster(ROSTER, {"team": " New  team ", "members": [{"id": "backend", "color": "#AABBCC", "repos": ["x"], "zone": "qa"}]})
        self.assertEqual(out["team"], "New team")
        be = out["members"][1]
        self.assertEqual((be["color"], be["repos"], be["zone"]), ("#aabbcc", ["api"], "eng"))
        self.assertEqual(ROSTER["team"], "Shop")  # the original is untouched

    def test_rejects_bad_input(self):
        for edit in ({"members": [{"id": "nobody", "name": "X"}]},
                     {"members": [{"id": "backend", "model": "opus\ntools: Bash"}]},
                     {"members": [{"id": "backend", "color": "red"}]},
                     {"members": [{"id": "backend", "name": "  "}]}):
            with self.assertRaises(ValueError, msg=edit):
                settings.apply_roster(ROSTER, edit)

    def test_rejects_non_dict_and_bad_member_shapes(self):
        for edit in (
            "not a dict",
            [1, 2],
            {"members": "not a list"},
            {"members": ["not a dict"]},
            {"members": [123]},
            {"members": [{"id": ["x"]}]},
            {"members": [{"id": {"nested": "dict"}}]},
            {"members": [{"id": 123}]},
            {"members": [{"id": None}]},
        ):
            with self.assertRaises(ValueError, msg=str(edit)):
                settings.apply_roster(ROSTER, edit)

    def test_text_that_would_break_the_agent_files_is_dropped(self):
        out = settings.apply_roster(ROSTER, {"members": [{"id": "backend", "name": 'Em"re\n*x*', "role": "A · B"}]})
        self.assertEqual(out["members"][1]["name"], "Emre x")
        self.assertEqual(out["members"][1]["role"], "A B")


class OfficeSettingsTest(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.addCleanup(setattr, settings, "PATH", settings.PATH)
        settings.PATH = self.tmp.name + "/team/settings.json"

    def test_defaults_merge_and_clean(self):
        self.assertEqual(settings.load(), settings._clean({}))
        s = settings.save({"ui": {"tabs": {"board": False}, "bogus": 1, "view": "3d"}, "hours": -5})
        self.assertFalse(s["ui"]["tabs"]["board"])
        self.assertTrue(s["ui"]["tabs"]["feed"])
        self.assertNotIn("bogus", s["ui"])
        self.assertEqual(s["ui"]["view"], "iso")
        self.assertEqual(s["ui"]["defaultTab"], "boards")  # the default tab was closed
        self.assertEqual(s["hours"], 0.25)
        s = settings.save({"ui": {"rooms": {"bench": False}}})
        self.assertFalse(s["ui"]["tabs"]["board"])  # earlier changes are kept
        self.assertFalse(settings.load()["ui"]["rooms"]["bench"])


if __name__ == "__main__":
    unittest.main()
